events.command:
/usr/bin/bash -lc "set -euo pipefail
required_columns='bioproject run_accession study_accession experiment_accession sample_accession biosample organism_taxid organism_name library_strategy library_source library_selection library_layout instrument_model run_total_spots run_total_bases'
for project in PRJNA1354216 PRJNA1339024; do
  metadata=\"final_answer/metadata/"'${project}.tsv"
  awk -F '"'\\t' -v project=\""'$project" -v required="$required_columns" '"'
    NR==1 {
      for (i=1; i<=NF; i++) col["'$i]=i
      n=split(required, req, " ")
      for (i=1; i<=n; i++) if (!(req[i] in col)) {print "missing column " req[i] > "/dev/stderr"; exit 10}
      next
    }
    {
      rows++
      if ($col["bioproject"] != project) {print "wrong project" > "/dev/stderr"; exit 11}
      run=$col["run_accession"]
      if (++seen[run] != 1) {print "duplicate run " run > "/dev/stderr"; exit 12}
      if ($col["library_layout"] != "SINGLE" && $col["library_layout"] != "PAIRED") {print "bad layout" > "/dev/stderr"; exit 13}
    }
    END {if (rows == 0) exit 14; print project "'"\\tmetadata_rows\\t\" rows}
  ' \""'$metadata"
done
awk -F '"'\\t' '
  NR==1 {
    for(i=1;i<=NF;i++) c["'$i]=i
    required[1]="bioproject"; required[2]="run_accession"; required[3]="library_layout"; required[4]="forward_path"; required[5]="reverse_path"
    for(i=1;i<=5;i++) if (!(required[i] in c)) exit 20
    next
  }
  {
    rows++
    run=$c["run_accession"]
    if (++seen[run] != 1) exit 21
    layout=$c["library_layout"]; fwd=$c["forward_path"]; rev=$c["reverse_path"]
    if (layout=="SINGLE" && rev!="") exit 22
    if (layout=="PAIRED" && rev=="") exit 23
    if (fwd ~ /''^'"\\// || rev ~ /"'^'"\\// || fwd ~ /"'^final_answer'"\\// || rev ~ /"'^final_answer'"\\//) exit 24
  }
  END {if(rows"'!=20) exit 25}
'"' final_answer/run_manifest.tsv
if "'! cmp -s <(awk -F '"'\\t' 'FNR==1 {for(i=1;i<=NF;i++) c["'$i]=i; next} {print $c["run_accession"]}'"' final_answer/metadata/*.tsv | sort) <(awk -F '\\t' 'NR==1{for(i=1;i<=NF;i++)c["'$i]=i;next}{print $c["run_accession"]}'"' final_answer/run_manifest.tsv | sort); then
  exit 26
fi
while IFS="'$'"'\\t' read -r project run layout forward reverse; do
  [ \""'$run" = "run_accession" ] && continue
  fwd="final_answer/$forward"
  [ -f "$fwd" ] || exit 30
  gzip -t "$fwd"
  fwd_stats=$(gzip -cd "$fwd" | awk -v run="$run" '"'
    NR%4==1 {records++; if (index("'$0,"@" run ".") != 1) bad=1}
    NR%4==2 {seq_len=length($0); bases+=seq_len}
    NR%4==3 {if (substr($0,1,1)!="+") bad=1}
    NR%4==0 {if (length($0)!=seq_len) bad=1}
    END {if (NR%4!=0 || bad || records==0) exit 31; print records "'"\\t\" bases}
  ')
  fwd_records="'${fwd_stats%%$'"'\\t'*}
  fwd_bases="'${fwd_stats#*$'"'\\t'}
  metadata=\"final_answer/metadata/"'${project}.tsv"
  expected=$(awk -F '"'\\t' -v run=\""'$run" '"'NR==1{for(i=1;i<=NF;i++)c["'$i]=i;next} $c["run_accession"]==run {print $c["run_total_spots"] "'"\\t\" "'$c["run_total_bases"]}'"' \""'$metadata")
  expected_spots=${expected%%$'"'\\t'*}
  expected_bases="'${expected#*$'"'\\t'}
  if [ \""'$layout" = "PAIRED" ]; then
    rev="final_answer/$reverse"
    [ -f "$rev" ] || exit 32
    gzip -t "$rev"
    rev_stats=$(gzip -cd "$rev" | awk -v run="$run" '"'
      NR%4==1 {records++; if (index("'$0,"@" run ".") != 1) bad=1}
      NR%4==2 {seq_len=length($0); bases+=seq_len}
      NR%4==3 {if (substr($0,1,1)!="+") bad=1}
      NR%4==0 {if (length($0)!=seq_len) bad=1}
      END {if (NR%4!=0 || bad || records==0) exit 33; print records "'"\\t\" bases}
    ')
    rev_records="'${rev_stats%%$'"'\\t'*}
    rev_bases="'${rev_stats#*$'"'\\t'}
    [ \""'$fwd_records" -eq "$rev_records" ] || exit 34
    [ "$fwd_records" -eq "$expected_spots" ] || exit 35
    [ $((fwd_bases + rev_bases)) -eq "$expected_bases" ] || exit 36
    paste <(gzip -cd "$fwd" | awk '"'NR%4==1{sub(/"'^@/,""); sub(/'"\\/1"'$/,""); print}'"') <(gzip -cd \""'$rev" | awk '"'NR%4==1{sub(/"'^@/,""); sub(/'"\\/2"'$/,""); print}'"') | awk -F '\\t' '"'$1!=$2{exit 37}'"'
    printf '%s\\t%s\\tspots=%s\\tbases=%s\\tsynchronized=yes\\n' \""'$run" "$layout" "$fwd_records" "$expected_bases"
  else
    [ "$fwd_records" -eq "$expected_spots" ] || exit 38
    [ "$fwd_bases" -eq "$expected_bases" ] || exit 39
    printf '"'%s\\t%s\\tspots=%s\\tbases=%s\\n' \""'$run" "$layout" "$fwd_records" "$fwd_bases"
  fi
done < final_answer/run_manifest.tsv
expected_file_count=35
actual_file_count=$(find final_answer -type f | wc -l)
[ "$actual_file_count" -eq "$expected_file_count" ] || exit 40
printf '"'run_sets\\tmatch\\t20\\nfinal_file_count\\tok\\t%s\\n' \""'$actual_file_count"'
